questionvariables.text:
/* Randomly select a Pythagorean triple [opposite (sin), adjacent (cos), hypotenuse].
   Each triple appears in both orders, so the larger side can be the sine or the cosine. */
triples : [[3,4,5], [4,3,5], [5,12,13], [12,5,13], [8,15,17], [15,8,17], [7,24,25], [24,7,25]];
tri : rand(triples);
sin_num : tri[1];
cos_num : tri[2];
hyp : tri[3];

/* Given sine value (third quadrant: sine is negative) */
given_sin : -sin_num/hyp;

/* Exact trigonometric ratios in quadrant III */
ta_cos : -cos_num/hyp;
ta_tan : sin_num/cos_num;

/* Exact coordinates of P */
ta_x : -cos_num/hyp;
ta_y : -sin_num/hyp;
ta_P : [ta_x, ta_y];

/* Reference angle in degrees, and theta = 180 + alpha */
ref_deg : float(atan(sin_num/cos_num)*180/%pi);
theta_deg : 180 + ref_deg;
ref_disp : dispdp(ref_deg, 1);
theta_disp : dispdp(theta_deg, 1);
ref_ans : decimalplaces(ref_deg, 1);    /* model answer shown to students: an ordinary number */

/* Possible student mistakes */
cos_wrongsign : -ta_cos;           /* positive cos */
cos_usedsin : sin_num/hyp;         /* size of sin given as cos (either sign) */
cos_nosqrt : cos_num^2/hyp^2;      /* forgot the square root (either sign) */
tan_wrongsign : -ta_tan;
tan_recip : cos_num/sin_num;       /* cos/sin instead of sin/cos */
P_swap : [ta_y, ta_x];
P_xsign : [-ta_x, ta_y];
P_ysign : [ta_x, -ta_y];
P_both : [-ta_x, -ta_y];
ref_theta : theta_deg;             /* gave theta instead of the reference angle */
ref_comp : 90 - ref_deg;           /* used cos/sin, giving the other acute angle */
ref_rad : float(atan(sin_num/cos_num));   /* calculator in radian mode */
